const NSIDC_LICENSE = "NSIDC Sea Ice Index, Version 4 — free to use with citation (doi:10.7265/a98x-0f50)";
const LINK_ONLY = "See source site";
const yt = (id: string) => `https://www.youtube.com/watch?v=${id}`;
const commons = (file: string) => `https://commons.wikimedia.org/wiki/File:${encodeURIComponent(file.replace(/ /g, "_"))}`;

/** A bundled photograph: licence, credit and the Wikimedia Commons page it came from. */
const photo = (p: {
  id: string; slug: string; title: string; description: string; alt: string; by: string; license: string; file: string; date: string | null;
  expedition?: string; station?: string; discipline: string[]; tags: string[];
}): Item =>
  base({
    id: p.id, type: "photo", title: p.title, description: `${p.description} Photo: ${p.by}. Licence: ${p.license}, via Wikimedia Commons.`,
    expedition_id: p.expedition ?? null, station_id: p.station ?? null, discipline: p.discipline, tags: p.tags, authors: [p.by], event_date: p.date,
    license: p.license, source_url: commons(p.file), media_url: `/media/${p.slug}.jpg`, alt_text: p.alt,
  });

/** A video hosted on YouTube by its publisher: embedded and credited, never re-hosted. */
const video = (v: { id: string; yt: string; title: string; description: string; by: string; expedition?: string; station?: string; discipline: string[]; tags: string[] }): Item =>
  base({
    id: v.id, type: "video", title: v.title, description: `${v.description} Published on YouTube by ${v.by}; embedded and credited here.`,
    expedition_id: v.expedition ?? null, station_id: v.station ?? null, discipline: v.discipline, tags: v.tags, authors: [v.by], event_date: null,
    license: "Standard YouTube licence (embedded)", source_url: yt(v.yt), external_url: yt(v.yt), media_url: yt(v.yt),
  });

/** A page hosted by another organisation: link and credit only. */
const link = (l: { id: string; type: Item["type"]; title: string; description: string; by: string; url: string; expedition?: string; discipline: string[]; tags: string[]; date?: string }): Item =>
  base({
    id: l.id, type: l.type, title: l.title, description: l.description, expedition_id: l.expedition ?? null, station_id: null,
    discipline: l.discipline, tags: l.tags, authors: [l.by], event_date: l.date ?? null, license: LINK_ONLY, source_url: l.url, external_url: l.url,
  });

