// photographs and videos are searchable through their caption and credit
for (const i of items) {
  if ((i.type === "photo" || i.type === "video") && !archiveNotes[i.id]) archiveNotes[i.id] = [`${i.title}. ${i.description}`];
}

/** Deterministic chunk IDs: item order × page. */
export function chunkId(itemId: string, page: number) {
  const n = Number(itemId.slice(-4));
  return sid(10000 + n * 10 + page);
}

// ------------------------------------------------------------ datasets: real NSIDC Sea Ice Index series
const seaIceCsv = (rows: SeaIceRow[]) => () => ["year,extent_million_km2,area_million_km2", ...rows.map(([y, e, a]) => `${y},${e ?? ""},${a ?? ""}`)].join("\n") + "\n";
const SEA_ICE_UNITS = { extent_million_km2: "million km²", area_million_km2: "million km²" };

export const datasetCsv: Record<string, { csv: () => string; units: Record<string, string> }> = {
  [ITEM.dArcticSep]: { csv: seaIceCsv(SEA_ICE.arcticSep), units: SEA_ICE_UNITS },
  [ITEM.dAntarcticFeb]: { csv: seaIceCsv(SEA_ICE.antarcticFeb), units: SEA_ICE_UNITS },
  [ITEM.dArcticMar]: { csv: seaIceCsv(SEA_ICE.arcticMar), units: SEA_ICE_UNITS },
  [ITEM.dAntarcticSep]: { csv: seaIceCsv(SEA_ICE.antarcticSep), units: SEA_ICE_UNITS },
};

